#include <cstdio>
#include <cstdlib>
#include <cmath>
#include <cstring>
#include <algorithm>
#include <unordered_map>
#include <vector>
#include <cassert>

typedef unsigned long long ul;
typedef long long ll;

const int MOD = 1000000007;

struct mi {
    int val;
    mi() : val(0) {}
    mi(ll v) {
        v %= MOD;
        if (v < 0) v += MOD;
        val = (int)v;
    }
    mi operator-() const { return mi(-val); }
    mi& operator+=(const mi& m) {
        if ((val += m.val) >= MOD) val -= MOD;
        return *this;
    }
    mi& operator-=(const mi& m) {
        if ((val -= m.val) < 0) val += MOD;
        return *this;
    }
    mi& operator*=(const mi& m) {
        val = (ll)val * m.val % MOD;
        return *this;
    }
    friend mi operator+(mi a, const mi& b) { return a += b; }
    friend mi operator-(mi a, const mi& b) { return a -= b; }
    friend mi operator*(mi a, const mi& b) { return a *= b; }
    friend mi operator/(mi a, const mi& b) { return a *= inv(b); }
    static mi inv(const mi& a) {
        ll x, y;
        ll g = extended_gcd(a.val, MOD, x, y);
        assert(g == 1);
        return mi(x);
    }
    static ll extended_gcd(ll a, ll b, ll& x, ll& y) {
        if (b == 0) { x = 1; y = 0; return a; }
        ll x1, y1;
        ll g = extended_gcd(b, a % b, x1, y1);
        x = y1;
        y = x1 - (a / b) * y1;
        return g;
    }
};

ul no[7];
int n;
mi p[7][7];

ul po(int x) {
    return (ul)1 << x;
}

int main() {
    scanf("%d", &n);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            int x;
            scanf("%d", &x);
            p[i][j] = mi(x) / mi(100);
        }
    }
    for (int i = 0; i < n; ++i) {
        no[i] = 0;
        for (int j = 0; j < (1 << n); ++j) {
            if (!((j >> i) & 1)) {
                no[i] |= po(j);
            }
        }
    }
    std::unordered_map<ul, mi> m;
    m[1] = mi(1);
    for (int i = 0; i < n; ++i) {
        std::unordered_map<ul, mi> M;
        for (auto& t : m) {
            for (int j = 0; j < (1 << n); ++j) {
                ul res = 0;
                mi prob = 1;
                for (int k = 0; k < n; ++k) {
                    if (j & (1 << k)) {
                        prob *= p[i][k];
                        res |= (t.first & no[k]) << (1 << k);
                    } else {
                        prob *= mi(1) - p[i][k];
                    }
                }
                M[res] += t.second * prob;
            }
        }
        m.swap(M);
    }
    ul target = po((1 << n) - 1);
    mi ans = m[target];
    printf("%d\n", ans.val);
    return 0;
}
